const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store'}});
const validDeck=deck=>Array.isArray(deck)&&deck.length===8&&new Set(deck).size===8&&deck.every(k=>CARDS[k]&&!CARDS[k].token);
