export default {async fetch(request,env,ctx){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return api(request,env,arenaAnimations);if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const key=url.pathname==='/'?'/index.html':url.pathname,asset=arenaAssets[key];if(!asset){const upstream=arenaRemoteAssets[key];if(!upstream)return new Response('No encontrado',{status:404});const origin=await fetch(upstream);if(!origin.ok)return new Response('Recurso no disponible',{status:502});const response=new Response(origin.body,{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=31536000, immutable','X-Content-Type-Options':'nosniff'}});return request.method==='HEAD'?new Response(null,{headers:response.headers}):response;}const bytes=Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset[0],'Cache-Control':url.pathname==='/'||/\.(html|js|css|json)$/.test(url.pathname)?'no-cache':'public, max-age=86400','X-Content-Type-Options':'nosniff'}});}};
